sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 16px; }
.wrm-head h2 { margin: 0; font-size: 22px; color: var(--ink); }
.wrm-count { font-size: 13px; color: var(--ink-3); }

.wrm-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }

.wrm-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-soft);
  overflow: hidden;
  display: flex; flex-direction: column;
}
.wrm-thumb { height: 110px; background: var(--surface-2); display: flex; align-items: center; justify-content: center; }
.wrm-thumb img { width: 100%; height: 100%; object-fit: cover; }
.wrm-noimg { font-size: 12px; color: var(--ink-3); padding: 0 12px; text-align: center; }

.wrm-body { padding: 13px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.wrm-name { font-size: 14px; font-weight: 500; color: var(--ink); }
.wrm-sub  { font-size: 11px; color: var(--ink-3); }
.wrm-foot { display: flex; align-items: center; justify-content: space-between; margin-top: auto; }

.wrm-pill {
  font-size: 11px; padding: 5px 12px;
  border-radius: var(--r-pill);
  background: var(--free-bg); color: var(--free-fg);
}
.wrm-cap { font-size: 11px; color: var(--ink-3); }

.wrm-empty {
  text-align: center; padding: 38px 20px;
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: var(--r-card);
  color: var(--ink-2);
}

sp_widget.script:
(function() {
  data.workspaces = [];

  var gr = new GlideRecord('x_1903615_worksp_0_workspace_options');
  // Story asks for AVAILABLE workspaces only. Confirm 'available'
  // is the stored value once you've run the sys_choice dump.
  gr.addQuery('status', 'available');
  gr.orderBy('workspace_name');
  gr.query();

  while (gr.next()) {
    var raw = gr.getValue('image');
    var url = '';

    if (raw) {
      // user_image fields don't store a URL. Depending on release
      // the column holds either a sys_attachment sys_id or a
      // filename on the shadow table. Handle both, and log what
      // we actually got so we can simplify this later.
      if (raw.indexOf('.iix') > -1 || raw.indexOf('.') > -1) {
        url = raw.charAt(0) === '/' ? raw : '/' + raw;
      } else {
        url = '/sys_attachment.do?sys_id=' + raw;
      }
      gs.info('WRM image raw value: [' + raw + '] -> ' + url);
    }

    data.workspaces.push({
      sys_id:   gr.getUniqueValue(),
      name:     gr.getDisplayValue('workspace_name'),
      type:     gr.getDisplayValue('workspace_type'),
      location: gr.getDisplayValue('location'),
      status:   gr.getDisplayValue('status'),
      capacity: gr.getValue('max_occupancy'),
      imageUrl: url
    });
  }

  data.count = data.workspaces.length;
})();
